arguments.command:
cat > /tmp/stackalloc_test/Program.cs << 'EOF'
Span<nint> nativeInts = stackalloc nint[4];
nativeInts[0] = 42;
nativeInts[1] = nint.MaxValue;
nativeInts[2] = nint.MinValue;
nativeInts[3] = (nint)123456789;

Console.WriteLine($"Span<nint> length: {nativeInts.Length}");
for (int i = 0; i < nativeInts.Length; i++)
    Console.WriteLine($"  [{i}] = {nativeInts[i]}");

Span<nuint> nativeUInts = stackalloc nuint[2];
nativeUInts[0] = nuint.MaxValue;
nativeUInts[1] = 0;

Console.WriteLine($"Span<nuint> length: {nativeUInts.Length}");
for (int i = 0; i < nativeUInts.Length; i++)
    Console.WriteLine($"  [{i}] = {nativeUInts[i]}");
EOF
